                channel: 0,
            },
            &world,
        );

        lane.on_input(
            InputEvent::NoteOff {
                note: 60,
                channel: 0,
            },
            &world,
        );
        // Anchor = 0, beats_per_bar = 4, so phrase_end = 4.
        // Near's fire_at = 2 ≤ 4 → kept.
        // Far's fire_at  = 8 > 4 → dropped.
        let near_kept = lane
            .pending_on
            .iter()
            .any(|p| (p.fire_at - 2.0).abs() < 0.001);
        let far_kept = lane
            .pending_on
            .iter()
            .any(|p| (p.fire_at - 8.0).abs() < 0.001);
        assert!(
            near_kept,
            "PhraseEnd should keep emissions within the current bar"
        );
        assert!(!far_kept, "PhraseEnd should drop emissions beyond the bar");
    }

    #[test]
    fn hold_mode_json_round_trip() {
        // Each variant should survive a JSON round-trip through the
        // wire format used by IPC + save/restore.
        for mode in [
            HoldMode::Cancel,
            HoldMode::NearFuture { tail_beats: 2.5 },
            HoldMode::PhraseEnd,
            HoldMode::Forever,
        ] {
            let json = crate::lane::hold_mode_to_json(mode);
            let parsed = crate::lane::hold_mode_from_json(&json)
                .expect("hold_mode_from_json should accept every emitted variant");
            assert_eq!(mode, parsed, "round-trip mismatch on {:?}", mode);
        }
        // Unknown shapes return None — caller falls back, doesn't crash.
        assert!(
            crate::lane::hold_mode_from_json(&serde_json::json!({ "kind": "bogus" })).is_none()
        );
        assert!(crate::lane::hold_mode_from_json(&serde_json::json!({ "nope": true })).is_none());
    }

    #[test]
    fn hold_mode_only_affects_target_player_note() {
        // Two held notes; release only one. The other's pending
        // emissions must be untouched even when global mode is Cancel.
        let (mut lane, world, transport) = fixture_with_long_delay_voice();
        *world.global_hold_mode.lock().unwrap() = HoldMode::Cancel;

        advance_to_beat(&transport, 0.0);
        lane.on_input(
            InputEvent::NoteOn {
                note: 60,
                velocity: 100,
                channel: 0,
            },
            &world,
        );
        lane.on_input(
            InputEvent::NoteOn {
                note: 64,
                velocity: 100,
                channel: 0,
            },
            &world,
        );
        let total_before = lane.pending_on.len();
        assert!(total_before >= 2);

        // Release only note 60.
        lane.on_input(
            InputEvent::NoteOff {
                note: 60,
                channel: 0,
            },
            &world,
        );

        // 60's pending should be gone; 64's should still be there.
        assert!(lane.pending_on.iter().all(|p| p.player_note != 60));
        assert!(lane.pending_on.iter().any(|p| p.player_note == 64));
    }

    /// Regression: in Cancel mode, the user reported notes ringing on
    /// after release. Root cause was that pending_off for already-
    /// emitted canon notes was scheduled at the canon voice's natural
    /// `voice_off_fire`, not `now`. Verify Cancel releases now.
    #[test]
    fn hold_mode_cancel_releases_emitted_notes_at_now() {
        let (mut lane, world, transport) = fixture();
        lane.set_enabled(true);
        // Single voice, delay=0, time_ratio=2 — emits NoteOn at beat 0
        // and (under Forever) would naturally release at 0.5 * 2.0 = 1.0.
        // Under Cancel we expect release at `now` (~0.5).
        let voice = CanonVoice::with_time_ratio(0.0, 2, 2.0);
        lane.set_voices(vec![voice]);
        *world.global_hold_mode.lock().unwrap() = HoldMode::Cancel;

        advance_to_beat(&transport, 0.0);
        lane.on_input(
            InputEvent::NoteOn {
                note: 60,
                velocity: 100,
                channel: 0,
            },
            &world,
        );
        // Drain the NoteOn so the canon note is "playing" on the synth.
        let _ = lane.tick(&world);

        advance_to_beat(&transport, 0.5);
        lane.on_input(
            InputEvent::NoteOff {
                note: 60,
                channel: 0,
            },
            &world,
        );

        let offs: Vec<f64> = lane
            .pending_off
            .iter()
            .filter(|p| p.player_note == 60)
            .map(|p| p.fire_at)
            .collect();
        assert!(
            !offs.is_empty(),
            "Cancel should still schedule a NoteOff to release the playing canon note"
        );
        for &off_at in &offs {
            assert!(
                (off_at - 0.5).abs() < 0.01,
                "Cancel should release at now (~0.5); got fire_at={} (natural voice_off_fire would be 1.0)",
                off_at
            );
        }
    }

    /// Per-voice Forever override should preserve the natural release
    /// time even when global is Cancel — proves voice > lane > global
    /// resolution works for pending_off too, not just pending_on.
    #[test]
    fn hold_mode_voice_forever_overrides_global_cancel_for_release() {
        let (mut lane, world, transport) = fixture();
        lane.set_enabled(true);
        // Voice with explicit Forever override, time_ratio=2 so natural
        // voice_off_fire differs from now.
        let mut voice = CanonVoice::with_time_ratio(0.0, 2, 2.0);
        voice.hold_mode = Some(HoldMode::Forever);
        lane.set_voices(vec![voice]);
        // Global = Cancel; voice override should win.
        *world.global_hold_mode.lock().unwrap() = HoldMode::Cancel;

        advance_to_beat(&transport, 0.0);
        lane.on_input(
            InputEvent::NoteOn {
                note: 60,
                velocity: 100,
                channel: 0,
            },
            &world,
        );
        let _ = lane.tick(&world);

        advance_to_beat(&transport, 0.5);
        lane.on_input(
            InputEvent::NoteOff {
                note: 60,
                channel: 0,
            },
            &world,
        );

        let offs: Vec<f64> = lane
            .pending_off
            .iter()
            .filter(|p| p.player_note == 60)
            .map(|p| p.fire_at)
            .collect();
        assert!(
            !offs.is_empty(),
            "voice override should still schedule a release"
        );
        for &off_at in &offs {
            assert!(
                (off_at - 1.0).abs() < 0.01,
                "voice Forever override should release at natural voice_off_fire (~1.0), got {}",
                off_at
            );
        }
    }

    /// C1 regression: when HoldMode::Cancel drops a still-PENDING
    /// canon NoteOn (delayed voice that hadn't fired yet at release),
    /// the matching pending_off MUST also be dropped — otherwise the
    /// synth gets a NoteOff for a NoteOn it never received. Without
    /// this fix, every Cancel on a delayed voice leaked an orphan
    /// NoteOff per emission.
    #[test]
    fn hold_mode_cancel_drops_orphan_note_off_for_unfired_voice() {
        let (mut lane, world, transport) = fixture_with_long_delay_voice();
        *world.global_hold_mode.lock().unwrap() = HoldMode::Cancel;

        advance_to_beat(&transport, 0.0);
        lane.on_input(
            InputEvent::NoteOn {
                note: 60,
                velocity: 100,
                channel: 0,
            },
            &world,
        );
        // NoteOn is pending but NOT drained — fixture voice has
        // delay_beats=4.0, so at beat 0.0 its fire_at is well in
        // the future and tick() would not emit it yet.
        assert!(
            lane.pending_on.iter().any(|p| p.player_note == 60),
            "fixture should leave a pending_on entry for the delayed voice"
        );

        advance_to_beat(&transport, 0.5);
        lane.on_input(
            InputEvent::NoteOff {
                note: 60,
                channel: 0,
            },
            &world,
        );

        // Cancel must drop pending_on AND the matching pending_off
        // we just pushed for the (unfired) voice. If either remains,
        // the synth either fires a stale NoteOn (regression on
        // pending_on side) or an orphan NoteOff (C1 bug).
        assert!(
            lane.pending_on.iter().all(|p| p.player_note != 60),
            "Cancel must drop pending_on for player_note=60"
        );
        assert!(
            lane.pending_off.iter().all(|p| p.player_note != 60),
            "Cancel must drop orphan pending_off for unfired voice; got {:?}",
            lane.pending_off
        );
    }

    /// C2 regression: rapid retrigger of the same player_note before
    /// the prior release drains must not accumulate duplicate
    /// pending_off entries. Each (player_note, voice_idx, canon_note)
    /// tuple should have at most one queued release at any time.
    #[test]
    fn rapid_retrigger_does_not_duplicate_pending_off() {
        let (mut lane, world, transport) = fixture();
        lane.set_enabled(true);
        // Single voice, time_ratio=2 so voice_off_fire is well in the
        // future and the pending_off doesn't drain naturally between
        // the two release cycles below.
        let voice = CanonVoice::with_time_ratio(0.0, 2, 2.0);
        lane.set_voices(vec![voice]);
        // Forever so we keep natural release scheduling on each cycle.
        *world.global_hold_mode.lock().unwrap() = HoldMode::Forever;

        advance_to_beat(&transport, 0.0);
        lane.on_input(
            InputEvent::NoteOn {
                note: 60,
                velocity: 100,
                channel: 0,
            },
            &world,
        );
        let _ = lane.tick(&world);
        advance_to_beat(&transport, 0.1);
        lane.on_input(
            InputEvent::NoteOff {
                note: 60,
                channel: 0,
            },
            &world,
        );
        let after_first = lane
            .pending_off
            .iter()
            .filter(|p| p.player_note == 60)
            .count();

        // Retrigger BEFORE the first release fires.
        advance_to_beat(&transport, 0.2);
        lane.on_input(
            InputEvent::NoteOn {
                note: 60,
                velocity: 100,
                channel: 0,
            },
            &world,
        );
        let _ = lane.tick(&world);
        advance_to_beat(&transport, 0.3);
        lane.on_input(
            InputEvent::NoteOff {
                note: 60,
                channel: 0,
            },
            &world,
        );
        let after_second = lane
            .pending_off
            .iter()
            .filter(|p| p.player_note == 60)
            .count();

        // The second cycle should REPLACE the first cycle's
        // pending_off entries, not append. Same voice emits the same
        // canon_note in both cycles, so dedup by (voice_idx, canon_note)
        // keeps the count flat. Without C2 fix this grows linearly.
        assert_eq!(
            after_second, after_first,
            "rapid retrigger should dedup pending_off; first={} second={}",
            after_first, after_second
        );
    }
}

